import React from 'react';
import ReactDOM from 'react-dom';
import { Grommet, Box, Select } from 'grommet';

const options = ['Option 1', 'Option 2', 'Option 3'];

const App = () => (
  <Grommet themeMode="light" full>
    {/* Dark background container */}
    <Box pad="medium" background="dark-1">
      <Box width="medium">
        {/* The arrow is not visible here */}
        <Select
          placeholder="Select an option"
          options={options}
          size="medium"
        />
      </Box>
    </Box>

    {/* Light background container */}
    <Box pad="medium" background="light-1">
      <Box width="medium">
        {/* The arrow is visible here */}
        <Select
          placeholder="Select an option"
          options={options}
          size="medium"
        />
      </Box>
    </Box>
  </Grommet>
);

ReactDOM.render(<App />, document.getElementById('root'));
